package kr.tong.sky;
import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import java.time.*;import java.util.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class)
@Config(sdk=35,packageName="kr.tong.sky",instrumentedPackages={"kr.tong.sky"})
public class CalendarOptimizationTest {
 JSONObject catalog()throws Exception{return new JSONObject().put("regions",new JSONObject().put("유럽",new JSONArray().put(new JSONObject().put("code","CDG")))) ;}
 JSONObject snapshot(boolean large)throws Exception{JSONObject raw=new JSONObject().put("carrier","KE").put("collectionMethod","MONTHLY_CALENDAR").put("origin","ICN").put("destination","CDG").put("month","2027-03").put("sourceUpdatedAt","2026-11-02T00:00:00Z").put("collectedAt","2026-11-02T00:05:00Z");JSONArray days=new JSONArray();for(int n=1;n<=31;n++){JSONObject d=new JSONObject().put("date",String.format(Locale.ROOT,"2027-03-%02d",n)).put("status","OBSERVED");boolean sunday=LocalDate.of(2027,3,n).getDayOfWeek()==DayOfWeek.SUNDAY;for(String f:Search.ALL_FIELDS)d.put(f,sunday&&Set.of("economyAward","prestigeAward","prestigeUpgrade").contains(f));if(large){JSONArray rows=new JSONArray();for(int i=0;i<20;i++)rows.put(new JSONObject().put("number","KE"+(100+i)).put("departureTime","12:00").put("status","AUDIT").put("detail","original observation audit ".repeat(20)));d.put("flights",rows);}days.put(d);}return raw.put("dates",days);}
 void same(JSONObject raw)throws Exception{String before=raw.toString();JSONObject selected=catalog();assertEquals(BaselineRepeatMarkerPolicy.calendar(raw,selected).toString(),RepeatMarkerPolicy.calendar(raw,selected).toString());assertEquals(before,raw.toString());JSONObject view=RepeatMarkerPolicy.calendar(raw,selected);view.getJSONArray("dates").getJSONObject(0).put("prestigeAward",false);assertEquals(before,raw.toString());}
 @Test public void completePartialUnknownAndDuplicateCalendarsRemainIdentical()throws Exception{for(String scenario:List.of("complete","partial","unknown","duplicate","missing")){JSONObject raw=snapshot(false);JSONArray days=raw.getJSONArray("dates");if(scenario.equals("partial"))days.getJSONObject(27).put("prestigeAward",false);if(scenario.equals("unknown"))days.getJSONObject(27).put("status","UNKNOWN");if(scenario.equals("duplicate"))days.put(new JSONObject(days.getJSONObject(27).toString()));if(scenario.equals("missing"))days.remove(27);same(raw);}}
 @Test public void legacyFlagsFallbackAndInvalidBooleanValidationRemainIdentical()throws Exception{for(String type:List.of("legacyAwardFlags","awardCalendarFlags")){JSONObject raw=snapshot(false),d=raw.getJSONArray("dates").getJSONObject(6),flags=new JSONObject();for(String f:Search.ALL_FIELDS)flags.put(f,d.get(f));d.put(type,flags);same(raw);flags.put("prestigeAward","true");same(raw);}}
 @Test public void detachedApplyPreservesBothRawAndProjectedInputs()throws Exception{JSONObject raw=snapshot(true),view=new JSONObject(raw.toString());String a=raw.toString(),b=view.toString();assertEquals(BaselineRepeatMarkerPolicy.apply(raw,view,catalog()).toString(),RepeatMarkerPolicy.apply(raw,view,catalog()).toString());assertEquals(a,raw.toString());assertEquals(b,view.toString());}
 @Test public void benchmarkCalendarProjectionWithLargeExistingAuditRecords()throws Exception{JSONObject raw=snapshot(true),selected=catalog();same(raw);for(int i=0;i<5;i++){BaselineRepeatMarkerPolicy.calendar(raw,selected);RepeatMarkerPolicy.calendar(raw,selected);}long start=System.nanoTime();for(int i=0;i<20;i++)BaselineRepeatMarkerPolicy.calendar(raw,selected);long before=System.nanoTime()-start;start=System.nanoTime();for(int i=0;i<20;i++)RepeatMarkerPolicy.calendar(raw,selected);long after=System.nanoTime()-start;System.out.println("CALENDAR_BENCHMARK baselineMs="+before/1e6+" optimizedMs="+after/1e6+" iterations=20");}
}
